 if(leaf==='notifications')inner=form('preferencesForm',select('In-app notifications','notifications',[['on','Show new activity'],['off','Keep notifications quiet']],s.preferences.notifications===false?'off':'on'),'Save preference')+'<p class="small muted">Notifications stay inside Duck & Bear. No private message contents are sent to email or a lock screen.</p>';
